proof.witness_factory:
import tempfile

from metaflow.cmd.develop.stub_generator import StubGenerator


def build_cases():
    """Yield StubGenerator receivers whose import tracking sets carry content."""
    seedings = (
        (("os",), ("test.module",)),
        (("json", "collections"), ("pkg.a", "pkg.b")),
    )
    for plain, typing_ in seedings:
        gen = StubGenerator(tempfile.mkdtemp(), include_generated_for=False)
        for name in plain:
            gen._imports.add(name)
        for name in typing_:
            gen._typing_imports.add(name)
        yield {"args": (gen,), "kwargs": {}}

