    try:
        second = target(*args, **kwargs)
    except Exception as exc:  # noqa: BLE001
        return {"raised_on_second": type(exc).__name__, "message": str(exc)}

    observation["same_instance"] = first is second
    observation["cached_on_second"] = "shutil" in vars(second)

