import inspect
import json
import os
_FACTORY_SOURCE = 'def build_cases():\n    """Generate case that exposes incorrect empty tuple handling.\n    \n    Spec S5 states that empty tuple should result in no keyword filtering,\n    meaning all paths should be returned, same as with None.\n    """\n    \n    # Pass empty tuple as keywords\n    # Gold: returns all default testpaths (no filtering)\n    # Mutant: enters filtering branch with no keywords, returns empty list\n    yield {\n        "args": (\n            [],  # paths - use default testpaths from pytest.ini\n            (),  # keywords - EMPTY TUPLE\n            [],  # args list to extend\n        ),\n        "kwargs": {}\n    }'
_OBSERVER_SOURCE = 'from sympy.testing.runtests_pytest import update_args_with_paths\n\ntarget = update_args_with_paths\n\ndef observe_case(case):\n    args = tuple(case["args"])\n    kwargs = dict(case["kwargs"])\n    \n    result = target(*args, **kwargs)\n    \n    # Return observation of how many paths were found\n    # Gold: should return multiple paths (default testpaths)\n    # Mutant: returns empty list\n    return {\n        "num_paths": len(result),\n        "has_paths": len(result) > 0\n    }'
def _validate_call_case(case):
    if not isinstance(case, dict):
        raise TypeError('case must be a dict')
    if set(case) != {'args', 'kwargs'}:
        raise ValueError("case must contain exactly 'args' and 'kwargs'")
    if not isinstance(case['args'], (tuple, list)):
        raise TypeError("case['args'] must be a tuple or list")
    if not isinstance(case['kwargs'], dict):
        raise TypeError("case['kwargs'] must be a dict")
    if not all(isinstance(key, str) for key in case['kwargs']):
        raise TypeError("case['kwargs'] keys must be strings")
def _validate_receiver(target, args):
    if inspect.ismethod(target) and target.__self__ is not None:
        return
    if not inspect.isfunction(target):
        return
    qualname = getattr(target, '__qualname__', '')
    if '<locals>' in qualname or '.' not in qualname:
        return
    try:
        parameters = list(inspect.signature(target).parameters.values())
    except (TypeError, ValueError):
        return
    if not parameters or parameters[0].name != 'self':
        return
    owner = inspect.getmodule(target)
    for part in qualname.rsplit('.', 1)[0].split('.'):
        owner = getattr(owner, part, None)
    if isinstance(owner, type) and (not args or not isinstance(args[0], owner)):
        raise TypeError(f'unbound method {qualname} requires an instance of {owner.__name__} as the first positional argument')
def _bind_target_call(target, case):
    args = tuple(case['args'])
    kwargs = dict(case['kwargs'])
    try:
        inspect.signature(target).bind(*args, **kwargs)
    except ValueError:
        pass
    except TypeError as exc:
        if os.environ.get('WITNESS_ALLOW_BIND_MISMATCH') != '1':
            raise TypeError(f'case does not match target signature: {exc}') from exc
    _validate_receiver(target, args)
def test_factory_witness():
    factory_ns = {}
    observer_ns = {}
    exec(_FACTORY_SOURCE, factory_ns)
    exec(_OBSERVER_SOURCE, observer_ns)
    target = observer_ns.get('target')
    if not callable(target):
        raise TypeError("witness_observer must expose callable global 'target'")
    for case in factory_ns['build_cases']():
        _validate_call_case(case)
        _bind_target_call(target, case)
        observation = observer_ns['observe_case'](case)
        print('__WITNESS_OBS__ ' + json.dumps(observation, sort_keys=True, ensure_ascii=False), flush=True)

