def build_cases():
    """Generate case that exposes incorrect empty tuple handling.

    Spec S5 states that empty tuple should result in no keyword filtering,
    meaning all paths should be returned, same as with None.
    """

    # Pass empty tuple as keywords
    # Gold: returns all default testpaths (no filtering)
    # Mutant: enters filtering branch with no keywords, returns empty list
    yield {
        "args": (
            [],  # paths - use default testpaths from pytest.ini
            (),  # keywords - EMPTY TUPLE
            [],  # args list to extend
        ),
        "kwargs": {}
    }

