def build_cases():
    """Yield cases that trigger keyword-based test matching."""
    # Case that triggers keyword matching for a known test function
    yield {
        "args": [[], ('bicycle',), []],
        "kwargs": {}
    }
    # Another case with a different keyword
    yield {
        "args": [[], ('3538',), []],
        "kwargs": {}
    }

proof.witness_observer:
from sympy.testing.runtests_pytest import update_args_with_paths

target = update_args_with_paths

def observe_case(case):
    args, kwargs = tuple(case["args"]), dict(case["kwargs"])
    try:
        result = target(*args, **kwargs)
    except Exception as exc:
        return {"raised": type(exc).__name__, "message": str(exc)}

    # Extract and return keyword-matched paths (those containing ::)
    # These are the paths where the format violation is observable
    keyword_paths = [p for p in result if '::' in p]
    return {"keyword_paths": sorted(keyword_paths)}

